// This code has been fully generated by an AI.

// Package fitfile decodes FIT activity files and derives the natural keys
// used for idempotent imports.
//
// Identity: the FIT file_id message identifies a recording uniquely through
// manufacturer, serial_number and time_created. The same recording therefore
// gets the same key regardless of how it arrives (Garmin Connect download,
// bulk export, USB copy) and regardless of its file name. Files without a
// complete file_id fall back to the SHA-256 of their content.
package fitfile

import (
	"bytes"
	"crypto/sha256"
	"encoding/hex"
	"errors"
	"fmt"
	"io"
	"math"
	"time"

	"github.com/muktihari/fit/decoder"
	"github.com/muktihari/fit/profile/basetype"
	"github.com/muktihari/fit/profile/filedef"
	"github.com/muktihari/fit/profile/mesgdef"
	"github.com/muktihari/fit/profile/typedef"
)

// MaxFileSize guards against unbounded memory use; real activity files are a
// few MB even for multi-day recordings.
const MaxFileSize = 64 << 20

// Summary is the condensed view of one FIT activity file. Integer metrics use
// 0 for "not recorded" (e.g. no heart rate strap).
type Summary struct {
	Key            string    `json:"key"`
	KeySource      string    `json:"key_source"` // "file_id" or "sha256"
	SHA256         string    `json:"sha256"`
	FileType       string    `json:"file_type"`
	Manufacturer   string    `json:"manufacturer"`
	ManufacturerID uint16    `json:"manufacturer_id"`
	Product        uint16    `json:"product"`
	ProductName    string    `json:"product_name,omitempty"`
	Serial         uint32    `json:"serial_number"`
	TimeCreated    time.Time `json:"time_created"`

	Sport     string    `json:"sport"`
	SubSport  string    `json:"sub_sport"`
	Sessions  int       `json:"sessions"`
	StartTime time.Time `json:"start_time"`
	// TZOffsetS is the device's UTC offset at the time of the activity; it
	// assigns activities to local days, weeks and months.
	TZOffsetS int     `json:"tz_offset_s"`
	DistanceM float64 `json:"distance_m"`
	TimerS    float64 `json:"timer_s"`
	ElapsedS  float64 `json:"elapsed_s"`
	AscentM   int     `json:"ascent_m"`
	DescentM  int     `json:"descent_m"`

	AvgSpeed   float64 `json:"avg_speed_mps"`
	MaxSpeed   float64 `json:"max_speed_mps"`
	AvgHR      int     `json:"avg_heart_rate"`
	MaxHR      int     `json:"max_heart_rate"`
	AvgPower   int     `json:"avg_power"`
	MaxPower   int     `json:"max_power"`
	AvgCadence int     `json:"avg_cadence"`

	Training Training `json:"training"`

	Records     int   `json:"records"`
	GPSPoints   int   `json:"gps_points"`
	HasHR       bool  `json:"has_heart_rate"`
	HasPower    bool  `json:"has_power"`
	HasCadence  bool  `json:"has_cadence"`
	HasAltitude bool  `json:"has_altitude"`
	DevFields   int   `json:"developer_fields"`
	BBox        *BBox `json:"bbox,omitempty"`
}

// BBox is the bounding box of all GPS points in degrees.
type BBox struct {
	MinLat, MinLon, MaxLat, MaxLon float64
}

// Training holds the training values Garmin devices write into the session
// summary. Zero means "not recorded"; TSS, IF and threshold power need a
// power meter and a configured FTP.
type Training struct {
	// Effect and AnaerobicEffect are Garmin's training effect (0–5).
	Effect          float64 `json:"training_effect,omitempty"`
	AnaerobicEffect float64 `json:"anaerobic_training_effect,omitempty"`
	// Load is Garmin's training load of the activity (EPOC based), the
	// value behind acute and chronic load on the watch.
	Load            float64 `json:"training_load,omitempty"`
	NormalizedPower int     `json:"normalized_power,omitempty"`
	TSS             float64 `json:"training_stress_score,omitempty"`
	IntensityFactor float64 `json:"intensity_factor,omitempty"`
	ThresholdPower  int     `json:"threshold_power,omitempty"`
	// RPE is the perceived exertion 1–10, Feel 0–100 (both entered on the watch).
	RPE  float64 `json:"rpe,omitempty"`
	Feel int     `json:"feel,omitempty"`
}

// Lap is one lap of an activity. StartOffsetS is relative to the activity
// start; zero metrics mean "not recorded".
type Lap struct {
	StartOffsetS float64 `json:"start_offset_s"`
	TimerS       float64 `json:"timer_s"`
	ElapsedS     float64 `json:"elapsed_s"`
	DistanceM    float64 `json:"distance_m"`
	AscentM      int     `json:"ascent_m"`
	DescentM     int     `json:"descent_m"`
	AvgSpeed     float64 `json:"avg_speed_mps"`
	MaxSpeed     float64 `json:"max_speed_mps"`
	AvgHR        int     `json:"avg_heart_rate"`
	MaxHR        int     `json:"max_heart_rate"`
	AvgPower     int     `json:"avg_power"`
	AvgCadence   int     `json:"avg_cadence"`
	// Trigger is the FIT lap trigger, e.g. "manual", "distance", "session_end".
	Trigger string `json:"trigger"`
}

// ZoneTime is the time spent in one zone. Zone 0 is the time below zone 1;
// time above the top boundary counts to the top zone.
type ZoneTime struct {
	Zone      int     `json:"zone"`
	Low, High float64 `json:"-"`
	Seconds   float64 `json:"seconds"`
}

// Zones holds Garmin's time in zones of the session and the thresholds the
// device used at the time of the activity.
type Zones struct {
	HR    []ZoneTime
	Power []ZoneTime
	// MaxHR, RestHR, ThresholdHR and FTP are 0 if not recorded.
	MaxHR       int
	RestHR      int
	ThresholdHR int
	FTP         int
	// Female selects the TRIMP weighting; from the user profile.
	Female bool
}

// Activity is a decoded activity file: summary, laps, zones and per-record streams.
type Activity struct {
	Summary
	Laps    []Lap
	Zones   Zones
	Stream  Stream
	Profile Profile
}

// Profile is the user profile stored by the device; zero values mean "not
// recorded".
type Profile struct {
	Age    int    // years at the time of the activity
	Gender string // "male", "female" or ""
}

func profile(act *filedef.Activity) Profile {
	p := act.UserProfile
	if p == nil {
		return Profile{}
	}
	out := Profile{Age: validU8(p.Age)}
	switch p.Gender {
	case typedef.GenderMale:
		out.Gender = "male"
	case typedef.GenderFemale:
		out.Gender = "female"
	}
	return out
}

// IdentityKey returns the natural key of a recording, or "" if the file_id is
// incomplete (serial number or creation time missing).
func IdentityKey(id *mesgdef.FileId) string {
	if id.SerialNumber == basetype.Uint32zInvalid || id.TimeCreated.IsZero() {
		return ""
	}
	// Numeric manufacturer id: stable even if the library renames enum strings.
	return fmt.Sprintf("fit:%d:%d:%d", uint16(id.Manufacturer), id.SerialNumber, id.TimeCreated.Unix())
}

// Parse reads a FIT activity file and returns its summary.
func Parse(r io.Reader) (Summary, error) {
	raw, err := ReadAll(r)
	if err != nil {
		return Summary{}, err
	}
	act, err := Decode(raw)
	if err != nil {
		return Summary{}, err
	}
	return act.Summary, nil
}

// ReadAll reads a FIT file into memory, enforcing MaxFileSize.
func ReadAll(r io.Reader) ([]byte, error) {
	raw, err := io.ReadAll(io.LimitReader(r, MaxFileSize+1))
	if err != nil {
		return nil, fmt.Errorf("read: %w", err)
	}
	if len(raw) > MaxFileSize {
		return nil, fmt.Errorf("file exceeds %d bytes", MaxFileSize)
	}
	return raw, nil
}

// ErrNotActivity marks valid FIT files that are not activities, e.g. the
// daily monitoring, sleep or settings files of a Garmin bulk export.
var ErrNotActivity = errors.New("not an activity file")

// Decode decodes a complete FIT activity file.
func Decode(raw []byte) (*Activity, error) {
	// A Garmin export holds about 40 non-activity files per activity; peeking
	// at file_id avoids decoding them completely.
	id, err := decoder.New(bytes.NewReader(raw)).PeekFileId()
	if err != nil {
		return nil, fmt.Errorf("decode: %w", err)
	}
	if id.Type != typedef.FileActivity {
		return nil, fmt.Errorf("%w (type %s)", ErrNotActivity, id.Type)
	}
	sum := sha256.Sum256(raw)
	fit, err := decoder.New(bytes.NewReader(raw)).Decode()
	if err != nil {
		return nil, fmt.Errorf("decode: %w", err)
	}
	act := filedef.NewActivity(fit.Messages...)

	s := Summary{
		SHA256:         hex.EncodeToString(sum[:]),
		FileType:       act.FileId.Type.String(),
		Manufacturer:   act.FileId.Manufacturer.String(),
		ManufacturerID: uint16(act.FileId.Manufacturer),
		Product:        act.FileId.Product,
		ProductName:    act.FileId.ProductName,
		Serial:         act.FileId.SerialNumber,
		TimeCreated:    act.FileId.TimeCreated.UTC(),
		Sessions:       len(act.Sessions),
		Records:        len(act.Records),
		DevFields:      len(act.FieldDescriptions),
	}
	if key := IdentityKey(&act.FileId); key != "" {
		s.Key, s.KeySource = key, "file_id"
	} else {
		s.Key, s.KeySource = "sha256:"+s.SHA256, "sha256"
	}

	summarizeSessions(&s, act.Sessions)
	stream := buildStream(&s, act.Records)
	s.TZOffsetS = tzOffset(act.Activity)
	return &Activity{Summary: s, Laps: laps(s.StartTime, act.Laps), Zones: zones(act, &s), Stream: stream, Profile: profile(act)}, nil
}

// tzOffset derives the UTC offset from the activity message. Offsets outside
// ±14 h indicate a broken local timestamp and are ignored.
func tzOffset(a *mesgdef.Activity) int {
	if a == nil || a.Timestamp.IsZero() || a.LocalTimestamp.IsZero() {
		return 0
	}
	// LocalTimestamp is "local wall clock encoded as UTC"; the difference is
	// the offset. Round to 15 minutes to absorb the seconds between both fields.
	off := a.LocalTimestamp.Sub(a.Timestamp).Round(15 * time.Minute)
	if off < -14*time.Hour || off > 14*time.Hour {
		return 0
	}
	return int(off.Seconds())
}

// summarizeSessions aggregates all sessions; multisport files contain several.
func summarizeSessions(s *Summary, sessions []*mesgdef.Session) {
	for i, ses := range sessions {
		if i == 0 {
			s.Sport = ses.Sport.String()
			s.SubSport = ses.SubSport.String()
			s.StartTime = ses.StartTime.UTC()
		} else if s.Sport != ses.Sport.String() {
			s.Sport, s.SubSport = "multisport", ""
		}
		s.DistanceM += valid(ses.TotalDistanceScaled())
		s.TimerS += valid(ses.TotalTimerTimeScaled())
		s.ElapsedS += valid(ses.TotalElapsedTimeScaled())
		if ses.TotalAscent != basetype.Uint16Invalid {
			s.AscentM += int(ses.TotalAscent)
		}
		if ses.TotalDescent != basetype.Uint16Invalid {
			s.DescentM += int(ses.TotalDescent)
		}
	}
	for _, ses := range sessions {
		s.Training.Load += valid(ses.TrainingLoadPeakScaled())
		s.Training.Effect = math.Max(s.Training.Effect, valid(ses.TotalTrainingEffectScaled()))
		s.Training.AnaerobicEffect = math.Max(s.Training.AnaerobicEffect, valid(ses.TotalAnaerobicTrainingEffectScaled()))
	}
	// Averages only from a single session; for multisport files they are
	// derived from the records, which mixes sports consistently.
	if len(sessions) != 1 {
		return
	}
	ses := sessions[0]
	s.AvgSpeed = valid(ses.EnhancedAvgSpeedScaled())
	s.MaxSpeed = valid(ses.EnhancedMaxSpeedScaled())
	s.AvgHR = validU8(ses.AvgHeartRate)
	s.MaxHR = validU8(ses.MaxHeartRate)
	s.AvgPower = validU16(ses.AvgPower)
	s.MaxPower = validU16(ses.MaxPower)
	s.AvgCadence = validU8(ses.AvgCadence)
	s.Training.NormalizedPower = validU16(ses.NormalizedPower)
	s.Training.TSS = valid(ses.TrainingStressScoreScaled())
	s.Training.IntensityFactor = valid(ses.IntensityFactorScaled())
	s.Training.ThresholdPower = validU16(ses.ThresholdPower)
	if ses.WorkoutRpe != basetype.Uint8Invalid && ses.WorkoutRpe > 0 {
		s.Training.RPE = float64(ses.WorkoutRpe) / 10
	}
	if ses.WorkoutFeel != basetype.Uint8Invalid {
		s.Training.Feel = int(ses.WorkoutFeel)
	}
}

// laps converts the lap messages; laps without duration (some devices write
// an empty lap at the end) are dropped.
func laps(start time.Time, in []*mesgdef.Lap) []Lap {
	out := make([]Lap, 0, len(in))
	for _, l := range in {
		lap := Lap{
			TimerS:     valid(l.TotalTimerTimeScaled()),
			ElapsedS:   valid(l.TotalElapsedTimeScaled()),
			DistanceM:  valid(l.TotalDistanceScaled()),
			AvgSpeed:   valid(l.EnhancedAvgSpeedScaled()),
			MaxSpeed:   valid(l.EnhancedMaxSpeedScaled()),
			AvgHR:      validU8(l.AvgHeartRate),
			MaxHR:      validU8(l.MaxHeartRate),
			AvgPower:   validU16(l.AvgPower),
			AvgCadence: validU8(l.AvgCadence),
			Trigger:    l.LapTrigger.String(),
		}
		if l.TotalAscent != basetype.Uint16Invalid {
			lap.AscentM = int(l.TotalAscent)
		}
		if l.TotalDescent != basetype.Uint16Invalid {
			lap.DescentM = int(l.TotalDescent)
		}
		if !l.StartTime.IsZero() && !start.IsZero() {
			lap.StartOffsetS = l.StartTime.Sub(start).Seconds()
		}
		if lap.TimerS <= 0 && lap.ElapsedS <= 0 {
			continue
		}
		out = append(out, lap)
	}
	return out
}

func valid(v float64) float64 {
	if math.IsNaN(v) || math.IsInf(v, 0) {
		return 0
	}
	return v
}

func validU8(v uint8) int {
	if v == basetype.Uint8Invalid {
		return 0
	}
	return int(v)
}

func validU16(v uint16) int {
	if v == basetype.Uint16Invalid {
		return 0
	}
	return int(v)
}

// zones reads the session's time_in_zone message. Power zones are only kept
// when power was recorded: with an FTP set but no power meter, Garmin
// reports the whole activity in power zone 1.
func zones(act *filedef.Activity, s *Summary) Zones {
	var z Zones
	if p := act.UserProfile; p != nil {
		z.RestHR = validU8(p.RestingHeartRate)
		z.Female = p.Gender == typedef.GenderFemale
	}
	for _, t := range act.ZonesTargets {
		z.MaxHR = max(z.MaxHR, validU8(t.MaxHeartRate))
		z.ThresholdHR = max(z.ThresholdHR, validU8(t.ThresholdHeartRate))
		z.FTP = max(z.FTP, validU16(t.FunctionalThresholdPower))
	}
	for _, t := range act.TimeInZones {
		if t.ReferenceMesg != typedef.MesgNumSession || t.ReferenceIndex != 0 {
			continue
		}
		if v := validU8(t.MaxHeartRate); v > 0 {
			z.MaxHR = v
		}
		if v := validU8(t.RestingHeartRate); v > 0 {
			z.RestHR = v
		}
		if v := validU8(t.ThresholdHeartRate); v > 0 {
			z.ThresholdHR = v
		}
		if v := validU16(t.FunctionalThresholdPower); v > 0 {
			z.FTP = v
		}
		if s.HasHR {
			hb := make([]float64, 0, len(t.HrZoneHighBoundary))
			for _, b := range t.HrZoneHighBoundary {
				if b != basetype.Uint8Invalid {
					hb = append(hb, float64(b))
				}
			}
			z.HR = zoneTimes(hb, t.TimeInHrZone)
		}
		if s.HasPower {
			pb := make([]float64, 0, len(t.PowerZoneHighBoundary))
			for _, b := range t.PowerZoneHighBoundary {
				if b != basetype.Uint16Invalid {
					pb = append(pb, float64(b))
				}
			}
			z.Power = zoneTimes(pb, t.TimeInPowerZone)
		}
	}
	return z
}

// zoneTimes maps Garmin's arrays to zones: bounds[i] is the upper bound of
// zone i (bounds[0] = lower bound of zone 1); times[0] is below zone 1 and
// times[len(bounds)] above the top bound. Times are in milliseconds.
func zoneTimes(bounds []float64, times []uint32) []ZoneTime {
	if len(bounds) < 2 {
		return nil
	}
	sec := func(i int) float64 {
		if i < len(times) && times[i] != basetype.Uint32Invalid {
			return float64(times[i]) / 1000
		}
		return 0
	}
	out := []ZoneTime{{Zone: 0, Low: 0, High: bounds[0], Seconds: sec(0)}}
	total := sec(0)
	for i := 1; i < len(bounds); i++ {
		out = append(out, ZoneTime{Zone: i, Low: bounds[i-1], High: bounds[i], Seconds: sec(i)})
		total += sec(i)
	}
	above := sec(len(bounds))
	out[len(out)-1].Seconds += above
	if total+above == 0 {
		return nil
	}
	return out
}
